function slerpDir(ax, ay, az, bx, by, bz, t) {
	const al = Math.hypot(ax, ay, az) || 1;
	const bl = Math.hypot(bx, by, bz) || 1;
	ax /= al;
	ay /= al;
	az /= al;
	bx /= bl;
	by /= bl;
	bz /= bl;
	const dot = Math.max(-1, Math.min(1, ax * bx + ay * by + az * bz));
	const theta = Math.acos(dot);
	if (theta < 1e-4) return {
		x: ax,
		y: ay,
		z: az
	};
	const s = Math.sin(theta);
	const w1 = Math.sin((1 - t) * theta) / s;
	const w2 = Math.sin(t * theta) / s;
	return {
		x: ax * w1 + bx * w2,
		y: ay * w1 + by * w2,
		z: az * w1 + bz * w2
	};
}
function clipPose(keys, u, cutLo, cutHi) {
	const x = Math.max(0, Math.min(1, u));
	let i = 0;
	while (i < keys.length - 2 && x >= keys[i + 1].u) i++;
	const a = keys[i];
	const b = keys[i + 1];
	const span = b.u - a.u || 1;
	let t = (x - a.u) / span;
	if (!(a.u >= cutLo && a.u < cutHi)) t = t * t * (3 - 2 * t);
	const lerp = (p, q) => p + (q - p) * t;
	const dir = slerpDir(a.dx, a.dy, a.dz, b.dx, b.dy, b.dz, t);
	return {
		u: x,
		hx: lerp(a.hx, b.hx),
		hy: lerp(a.hy, b.hy),
		hz: lerp(a.hz, b.hz),
		dx: dir.x,
		dy: dir.y,
		dz: dir.z,
		sp: lerp(a.sp, b.sp),
		sy: lerp(a.sy, b.sy),
		sz: lerp(a.sz, b.sz),
		hyaw: lerp(a.hyaw, b.hyaw),
		hp: lerp(a.hp, b.hp),
		knee: lerp(a.knee, b.knee)
	};
}
function gsSwingPose(u) {
	return clipPose(GS_SWING, u, .38, .52);
}
