	function trustQuickening(pup) {
		const rows = useGame.getState().trustVitals[pup.def.id]?.buffs;
		if (!rows) return 1;
		let jig = false;
		let flee = false;
		for (const buff of rows) {
			if (buff.name === "Chocobo Jig") jig = true;
			if (buff.name === "Flee") flee = true;
		}
		return jig && !flee ? 1 + CHOCOBO_MOVE : 1;
	}
