	function splashElement(splash) {
		if (splash.element && ELEMENT_LOOK[splash.element]) return splash.element;
		const card = spellByName(splash.spell);
		const element = card ? castElement(card) : null;
		return element && ELEMENT_LOOK[element] ? element : null;
	}
	/**
	* The area already played on the main target.
	* The other Tropical Rarab gets that spell's own land if a status stuck,
	* or a small impact if the area was only damage.
	*/
	function playFoeSplash(splash) {
		if (!splash) return;
		const at = splash.foe === "kin" ? kinPos : harePos;
		const names = splash.enfeebles || [];
		const downs = splash.debuffs || [];
		const savedX = harePos.x;
		const savedZ = harePos.z;
		harePos.x = at.x;
		harePos.z = at.z;
		try {
			for (const name of names) if (name === "Helix") {
				const element = splashElement(splash);
				if (element) spawnHelixLand(element, at.x, at.z);
			} else if (name === "Diaga") spawnDiaLand(at.x, at.z, "Dia");
			else spawnEnfeebleLand(name, false);
			for (const name of downs) spawnDebuffPulse(name, true, at.x, at.z);
			if (names.length === 0 && downs.length === 0 && splash.dmg > 0) {
				const element = splashElement(splash);
				if (element) spawnSplashTap(element, at.x, at.z);
			}
			if (splash.dmg > 0) spawnFloater(String(splash.dmg), false, at.x, 1.35, at.z);
		} finally {
			harePos.x = savedX;
			harePos.z = savedZ;
		}
	}
