	function castBodyOn() {
		return elementalChantU() != null || enfeeblingChantU() != null || enhancingChantU() != null || ninjutsuChantU() != null || songChantU() != null || summonChantU() != null || geomancyChantU() != null || castToss > 0;
	}
	function syncChantWeapon() {
		const casting = castBodyOn();
		const summoning = summonChantU() != null || castRelease === "summoning";
		const gear = hero.armR.gear;
		const drawn = gear.parent === hero.armR.sword;
		if (casting && drawn && !summoning) {
			gear.visible = false;
			if (gearId === "cesti") hero.cestiL.visible = false;
			chantHidWeapon = true;
		} else if (chantHidWeapon && (!casting || summoning)) {
			gear.visible = true;
			if (gearId === "cesti") hero.cestiL.visible = true;
			chantHidWeapon = false;
		}
		const shield = hero.armL.shield;
		const blade = hero.armL.offBlade;
		if (casting && shield.visible) {
			shield.visible = false;
			chantHidShield = true;
		}
		if (casting && blade && blade.visible && blade.parent === hero.armL.hand) {
			blade.visible = false;
			chantHidBlade = true;
		} else if (!casting && (chantHidShield || chantHidBlade)) {
			const kind = ITEMS[useGame.getState().loadout.sub ?? ""]?.kind ?? "";
			if (chantHidShield) {
				shield.visible = kind === "Shield";
				chantHidShield = false;
			}
			if (chantHidBlade && blade) {
				blade.visible = isOffhandWeapon(ITEMS[useGame.getState().loadout.sub ?? ""]);
				chantHidBlade = false;
			}
		}
	}
	function songChantU() {
		const cast = useGame.getState().cast;
		const spell = cast ? spellByName(cast.name) : null;
		if (!cast || !(cast.total > 0) || spell?.school !== "singing") return null;
		return chantClock(cast) % CHANT_LOOP / CHANT_LOOP;
	}
	function songKindOf(rangeId) {
		const kind = ITEMS[rangeId ?? ""]?.kind;
		if (kind === "Wind") return "wind";
		if (kind === "String") return "string";
		return "voice";
	}
