	function peopleInSong(x, z) {
		const found = [];
		if (Math.hypot(px - x, pz - z) <= 12) found.push({
			x: px,
			z: pz
		});
		for (const pup of puppets) {
			if (!pup.body.root.visible) continue;
			if (Math.hypot(pup.x - x, pup.z - z) <= 12) found.push({
				x: pup.x,
				z: pup.z
			});
		}
		if (!found.length) found.push({
			x,
			z
		});
		return found;
	}
