		const stir = u * Math.PI * 2;
		const c = Math.cos(stir);
		const s = Math.sin(stir);
		const bob = s * .012 * enter;
		hero.hips.position.y = .78 + bob;
		setBoneEuler(hero.hips, .04 * enter, 0, 0);
		setBoneEuler(hero.legR.upper, .05 * enter, 0, 0);
		setBoneEuler(hero.legL.upper, .05 * enter, 0, 0);
		setBoneEuler(hero.legR.lower, .08 * enter, 0, 0);
		setBoneEuler(hero.legL.lower, .08 * enter, 0, 0);
		setBoneEuler(hero.spine, .05 * enter, 0, 0);
