		const g = new Group();
		const cup = new Mesh(new CylinderGeometry(.045, .09, .14, 8), toon(13936214));
		cup.position.y = -.02;
		const crown = new Mesh(new SphereGeometry(.035, 6, 5), toon(15984336));
		crown.position.y = .07;
		const clapper = new Mesh(new SphereGeometry(.02, 6, 5), toon(10066329));
		clapper.position.y = -.06;
		g.add(cup, crown, clapper);
