			const at = heroPoint(.02, 1.12, .34);
			const glint = new Mesh(new BoxGeometry(.018, .018, .26), plainMat(15269844, .88));
			glint.position.set(at.x, at.y, at.z);
			glint.rotation.y = yaw;
