			if (!mesh) {
				if (row.type === "wyvern") mesh = buildWyvern(toon);
				else if (row.type === "jug") mesh = buildCourier(toon);
				else if (row.type === "automaton") mesh = buildAutomaton(toon);
				else mesh = buildAvatar(toon);
				mesh.root.userData.petId = row.id;
				mesh.autoSide = i % 2 === 0 ? "L" : "R";
				petMeshes.set(row.id, mesh.root);
				scene.add(mesh.root);
				spareMeshes.set(row.id, mesh);
			}
			const pet = row.pet;
			mesh.root.visible = true;
			if (row.type === "avatar" && mesh.painted !== pet.id) {
				paintAvatar(mesh, pet.id);
				mesh.painted = pet.id;
			}
			if (row.type === "automaton") mesh.dress(state.autoHead, state.autoFrame);
			const fighting = foeUp && (row.type === "jug" ? pet.stance === "fight" : row.type === "automaton" ? pet.stance === "fight" : row.type === "avatar" ? pet.assault === true : true);
			const side = (i % 2 === 0 ? 1 : -1) * (1.7 + Math.floor(i / 2) * .7);
			if (!mesh.placed) {
				const face2 = fwd(yaw);
				mesh.root.position.set(px - face2.x * PET_FOLLOW_BACK + face2.z * side, 0, pz - face2.z * PET_FOLLOW_BACK - face2.x * side);
				mesh.placed = true;
			}
			const hx = harePos.x - px;
			const hz = harePos.z - pz;
			const span2 = Math.hypot(hx, hz) || 1;
			const tx = fighting ? harePos.x - hx / span2 * 1.45 + hz / span2 * side : px + fwd(yaw).z * side;
			const tz = fighting ? harePos.z - hz / span2 * 1.45 - hx / span2 * side : pz - fwd(yaw).x * side;
			movePetTight(mesh, tx, tz, dt);
			const held = clampWorld(mesh.root.position.x, mesh.root.position.z, .4);
			const dry = leaveWater(held.x, held.z, .4);
			mesh.root.position.x = dry.x;
			mesh.root.position.z = dry.z;
			const faceX = fighting ? harePos.x : px;
			const faceZ = fighting ? harePos.z : pz;
			const fdx = faceX - mesh.root.position.x;
			const fdz = faceZ - mesh.root.position.z;
			if (fdx * fdx + fdz * fdz > 1e-4) mesh.root.rotation.set(0, Math.atan2(fdx, fdz), 0);
			const reach = Math.hypot(harePos.x - mesh.root.position.x, harePos.z - mesh.root.position.z);
			const limit = row.type === "automaton" ? state.autoFrame === "sharpshot" ? 6.2 : state.autoFrame === "stormwaker" ? 4.2 : 1.85 : 1.85;
			noteSparePlace(row.id, mesh.root.position.x, mesh.root.position.z, fighting && reach <= limit);
