		streak.lookAt(harePos.x, 1.05, harePos.z);
		streak.userData.ownGeo = true;
		scene.add(streak);
		embers.push({
			mesh: streak,
			life: .28,
			max: .28,
			vy: 0,
			vx: 0,
			vz: 0,
			hold: .04
		});
