	function onHandMark(name, i) {
		if (name === "Combo" || name === "Raging Fists") spawnImpact(i % 2 === 0 ? -1 : 1, name === "Raging Fists" ? 1.05 + i % 3 * .06 : 1.12);
		else if (name === "Shoulder Tackle") spawnTackleHit();
		else if (name === "One Inch Punch") spawnInchRipple();
		else if (name === "Backhand Blow") spawnBackhandArc();
		else if (name === "Spinning Attack") spawnSpinRing();
		else if (name === "Howling Fist") spawnHowlingWave();
		else if (name === "Dragon Kick") spawnKickFlash(i === 1);
		else if (name === "Asuran Fists") {
			spawnImpact(i % 2 === 0 ? -1 : 1, 1.02 + i % 4 * .08);
			spawnAsuraGhost();
			spawnAsuraGhost();
		}
	}
	function tickHandTrail(name, p) {
		const now = timer.getElapsed();
		if (name === "Asuran Fists" && p > .04 && p < .94 && now - lastTrail > .032) {
			lastTrail = now;
			spawnAsuraGhost();
		} else if (name === "Spinning Attack" && p > .1 && p < .84 && now - lastTrail > .05) {
			lastTrail = now;
			spawnSpinPuff();
		} else if (name === "Backhand Blow" && p > .18 && p < .64 && now - lastTrail > .045) {
			lastTrail = now;
			spawnFistGlint();
		}
	}
