	let schBook = null;
	function ensureSchBook() {
		if (schBook) return schBook;
		const g = new Group();
		const coverL = new Mesh(new BoxGeometry(.2, .02, .15), plainMat(4868128, .96));
		coverL.position.x = -.1;
		coverL.userData.ownGeo = true;
		const coverR = new Mesh(new BoxGeometry(.2, .02, .15), plainMat(4868128, .96));
		coverR.position.x = .1;
		coverR.userData.ownGeo = true;
		const left = new Group();
		const right = new Group();
		left.add(coverL);
		right.add(coverR);
		const pages = [];
		for (let i = 0; i < 3; i++) {
			const page = new Mesh(new BoxGeometry(.16, .008, .12), plainMat(13934678, .92));
			page.position.y = .018 + i * .006;
			page.userData.ownGeo = true;
			pages.push(page);
			g.add(page);
		}
		const leaf = new Mesh(new BoxGeometry(.14, .01, .11), plainMat(16053476, .95));
		leaf.position.y = .045;
		leaf.visible = false;
		leaf.userData.ownGeo = true;
		g.add(left, right, leaf);
		g.visible = false;
		scene.add(g);
		schBook = {
			g,
			left,
			right,
			coverL,
			coverR,
			pages,
			leaf
		};
		return schBook;
	}
	function poseSchBook(open) {
		const book = ensureSchBook();
		const u = 1 - jaT / Math.max(jaDur, .001);
		const both = jaName === "Tabula Rasa" || jaName === "Enlightenment";
		const dark = schDarkJa(jaName) && !both;
		const cover = dark ? 2752800 : 4868128;
		const page = both ? 16053476 : dark ? 9067712 : 13934678;
		book.g.visible = true;
		book.coverL.material.color.setHex(both ? 4868128 : cover);
		book.coverR.material.color.setHex(both ? 2752800 : cover);
		for (const sheet of book.pages) sheet.material.color.setHex(page);
		let spread = open;
		if (schStratagem(jaName)) spread = Math.sin(Math.min(1, u / .55) * Math.PI) * .55;
		else if (schAddendum(jaName)) spread = .82;
		else if (jaName === "Modus Veritas") spread = u < .4 ? jaBlend(u / .4) : .9;
		else if (jaName === "Tabula Rasa") spread = Math.min(1, open * 1.2);
		book.left.rotation.y = spread * 1.2;
		book.right.rotation.y = -spread * 1.15;
		book.leaf.visible = schAddendum(jaName);
		if (book.leaf.visible) {
			const slide = Math.min(1, u / .8);
			book.leaf.position.x = .18 * (1 - slide);
			book.leaf.material.color.setHex(jaName === "Addendum: Black" ? 9067712 : 16053476);
		}
		hero.armL.hand.getWorldPosition(_hilt);
		const face = fwd(yaw);
		const lift = jaName === "Tabula Rasa" ? .2 : .06;
		book.g.position.set(_hilt.x + face.x * .06, Math.max(1.02, _hilt.y) + lift, _hilt.z + face.z * .06);
		book.g.rotation.set(0, yaw, 0);
		const scale = jaName === "Tabula Rasa" ? 1.55 : schStratagem(jaName) ? .7 : jaName === "Modus Veritas" ? .58 : 1;
		book.g.scale.setScalar(scale);
	}
	function poseHelixBook() {
		const state = useGame.getState();
		const cast = state.cast;
		if (!(cast ? spellByName(cast.name) : null)?.helix || state.mainJob !== "SCH" && state.subJob !== "SCH") return;
		const book = ensureSchBook();
		const dark = state.buffs.some((buff) => buff.name === "Dark Arts");
		const both = state.buffs.some((buff) => buff.name === "Tabula Rasa");
		const cover = dark ? 2752800 : 4868128;
		const page = both ? 16053476 : dark ? 9067712 : 13934678;
		book.g.visible = true;
		book.leaf.visible = false;
		book.coverL.material.color.setHex(both ? 4868128 : cover);
		book.coverR.material.color.setHex(both ? 2752800 : cover);
		for (const sheet of book.pages) sheet.material.color.setHex(page);
		const u = elementalChantU() ?? 0;
		const spread = .42 + Math.sin(u * Math.PI) * .48;
		book.left.rotation.y = spread * 1.15;
		book.right.rotation.y = -spread * 1.08;
		hero.root.updateMatrixWorld(true);
		hero.armL.hand.getWorldPosition(_hilt);
		const face = fwd(yaw);
		book.g.position.set(_hilt.x + face.x * .1, Math.max(1.08, _hilt.y) + .04, _hilt.z + face.z * .1);
		book.g.rotation.set(-.65, yaw, 0);
		book.g.scale.setScalar(.82);
	}
