	/**
	* Retail gun presentation. The piece comes to the shoulder, holds, then kicks.
	* Leaden Salute is the one that salutes: the off hand goes to the brow and
	* stays there until the shot. Coronach and Wildfire hold the piece back
	* while the muzzle charges. Sniper Shot barely climbs. Slug Shot and
	* Detonator kick hard. Last Stand and Blast Shot are twofold, so the
	* piece kicks twice. Blast Shot and Numbing Shot are short-ranged, so the
	* barrel is pushed forward instead of shouldered.
	*/
	function poseGunAim(nock, open, away, ws) {
		const salute = ws === "Leaden Salute";
		const charge = ws === "Coronach" || ws === "Wildfire" || ws === "Trueflight";
		const sniper = ws === "Sniper Shot";
		const heavyKick = ws === "Slug Shot" || ws === "Detonator" || ws === "Coronach" || ws === "Wildfire";
		const twofold = ws === "Last Stand" || ws === "Blast Shot";
		const close = ws === "Blast Shot" || ws === "Numbing Shot";
		const restRx = -.22;
		const restRy = 1.12;
		const restRz = .28;
		const aimZ = close ? 1.42 : charge ? .92 : 1.18;
		const recoilZ = close ? 1.05 : sniper ? 1.02 : heavyKick ? .42 : .7;
		let kickOpen = open;
		if (twofold) {
			const pulse = open < .5 ? open / .5 : (open - .5) / .5;
			kickOpen = Math.sin(Math.min(1, pulse) * Math.PI);
		}
		let hx = close ? -.02 : -.08;
		let hy = charge ? 1.34 : sniper ? 1.28 : 1.22;
		let hz = aimZ + (recoilZ - aimZ) * kickOpen;
		hx = hx + (restRx - hx) * away;
		hy = hy + (restRy - hy) * away;
		hz = hz + (restRz - hz) * away;
		hx = restRx + (hx - restRx) * nock;
		hy = restRy + (hy - restRy) * nock;
		hz = restRz + (hz - restRz) * nock;
		placeRangedHand(hero.armR, hx, hy, hz, hx - .28, hy - .02, hz - .72, true);
		let lx = .16;
		let ly = 1.05;
		let lz = .18;
		if (salute) {
			const up = nock * (1 - Math.min(1, open * 1.4));
			lx = .16 + -.12 * up;
			ly = 1.05 + (1.7 - 1.05) * up;
			lz = .18 + .06 * up;
		} else {
			lx = .16 + .19999999999999998 * nock;
			ly = 1.05 + -.15000000000000002 * nock;
			lz = .18 + -.22999999999999998 * nock;
		}
		lx = lx + (.16 - lx) * away;
		ly = ly + (1.05 - ly) * away;
		lz = lz + (.18 - lz) * away;
		const brow = salute && open < .35;
		placeRangedHand(hero.armL, lx, ly, lz, brow ? lx + .02 : lx + .18, brow ? ly + .06 : ly + .42, lz - .16, false);
		const kick = twofold ? kickOpen * .2 : open > 0 && open < .85 ? Math.sin(open * Math.PI) * (sniper ? .05 : heavyKick ? .32 : .18) : 0;
		aimFlint(hero.flint, kick);
		hero.bow.visible = false;
		hero.crossbow.visible = false;
	}
