	function shotCardTexture(element) {
		if (shotCardTex[element]) return shotCardTex[element];
		const look = ELEMENT_LOOK[element] || ELEMENT_LOOK.fire;
		const dark = element === "dark";
		const light = element === "light";
		const paper = dark ? "#140c18" : light ? "#f7f1e4" : "#1a120c";
		const ink = dark || !light ? "#f4ecd4" : "#1a1208";
		const wash = shotCss(look.color);
		const accent = shotCss(look.accent);
		const word = element === "thunder" ? "THUNDER" : element.toUpperCase();
		const c = document.createElement("canvas");
		c.width = 256;
		c.height = 384;
		const g = c.getContext("2d");
		g.fillStyle = paper;
		g.fillRect(0, 0, 256, 384);
		g.strokeStyle = accent;
		g.lineWidth = 10;
		g.strokeRect(16, 16, 224, 352);
		g.strokeStyle = wash;
		g.lineWidth = 4;
		g.strokeRect(28, 28, 200, 328);
		g.fillStyle = wash;
		g.globalAlpha = dark ? .35 : .9;
		g.beginPath();
		g.arc(128, 132, 46, 0, Math.PI * 2);
		g.fill();
		g.globalAlpha = 1;
		g.fillStyle = ink;
		g.font = "700 42px Georgia";
		g.textAlign = "center";
		g.textBaseline = "middle";
		g.fillText(word, 128, 250);
		g.font = "28px Georgia";
		g.fillText("QUICK DRAW", 128, 304);
		const tex = new CanvasTexture(c);
		tex.colorSpace = SRGBColorSpace;
		tex.needsUpdate = true;
		shotCardTex[element] = tex;
		return tex;
	}
