			blendBone(body.legL.upper, -.8, 0, .1, knee);
			blendBone(body.legR.lower, 1.45, 0, 0, knee);
			blendBone(body.legL.lower, 1.25, 0, 0, knee);
			blendBone(body.spine, .28, 0, 0, knee);
