		blendBone(body.legR.upper, -.16, .08, -.1, open);
		blendBone(body.legL.upper, .06, -.12, .08, open);
		blendBone(body.legR.lower, .38, 0, 0, open);
		blendBone(body.legL.lower, .18, 0, 0, open);
