	function endPuppetDeath(pup) {
		if (pup.corpse < 0 && !pup.deathIcon) return;
		pup.corpse = -1;
		pup.body.hips.position.y = .78;
		if (pup.deathIcon) pup.deathIcon.visible = false;
	}
	function holdPuppetCorpse(pup, dt) {
		if (pup.corpse < 0) pup.corpse = 0;
		const before = pup.corpse;
		pup.corpse += dt;
		if (pup.attack > 0) {
			pup.driver.stopAttack();
			pup.attack = 0;
			pup.skill = "";
		}
		pup.swing = 0;
		pup.jaT = 0;
		pup.toss = 0;
		clearTrustChant(pup);
		const quarry = playerFoe() === "kin" ? kinPos : harePos;
		const hareDist = Math.hypot(quarry.x - pup.x, quarry.z - pup.z) || 1e-4;
		pup.body.root.position.set(pup.x, 0, pup.z);
		pup.body.root.visible = true;
		applyFacing(pup.body.root, pup.aim || 0, basis, xAxis, yAxis, zAxis);
		noteTrustPlace(pup.def.id, hareDist, false, Math.hypot(px - pup.x, pz - pup.z), pup.x, pup.z);
		pup.driver.update(0, 0, false, reduced);
		poseHumanDeath(pup.body, pup.corpse);
		pup.deathIcon = placeDeathIcon(pup.deathIcon, pup.x, pup.z, pup.aim || 0, pup.corpse);
		if (before < .58 && pup.corpse >= .58) puffCorpse(pup.x, pup.z, pup.aim || 0);
	}
	function tendHeroDeath(dt) {
		if (!useGame.getState().ko) {
			if (heroCorpse >= 0) {
				heroCorpse = -1;
				hero.hips.position.y = .78;
				hero.root.position.y = 0;
			}
			if (heroDeathIcon) heroDeathIcon.visible = false;
			return;
		}
		if (heroCorpse < 0) heroCorpse = 0;
		const before = heroCorpse;
		heroCorpse += dt;
		hero.root.position.y = 0;
		poseHumanDeath(hero, heroCorpse);
		heroDeathIcon = placeDeathIcon(heroDeathIcon, px, pz, yaw, heroCorpse);
		if (before < .58 && heroCorpse >= .58) puffCorpse(px, pz, yaw);
	}
	function poseHeal() {
		beginHealHold();
		const phaseNow = useGame.getState().healPhase;
		const u = smoothStep(Math.min(1, healClock / Math.max(phaseNow === "up" ? HEAL_UP : HEAL_DOWN, .001)));
		const a = phaseNow === "down" ? u : phaseNow === "up" ? 1 - u : 1;
		const breath = phaseNow === "loop" ? Math.sin(timer.getElapsed() * 1.7) : 0;
		hero.hips.position.y = .78 - .58 * a + breath * .01;
		setBoneEuler(hero.hips, .06 * a, 0, 0);
		setBoneEuler(hero.legR.upper, .55 * a, 0, -.35 * a);
		setBoneEuler(hero.legR.lower, -1.9 * a, 0, 0);
		setBoneEuler(hero.legR.foot.parent, .8 * a, 0, 0);
		setBoneEuler(hero.legL.upper, -.95 * a, 0, .22 * a);
		setBoneEuler(hero.legL.lower, 1.45 * a, 0, 0);
		setBoneEuler(hero.legL.foot.parent, -.35 * a, 0, 0);
		setBoneEuler(hero.spine, .12 * a + breath * .035, .04 * a, 0);
		const head = hero.spine.getObjectByName("head");
		if (head) setBoneEuler(head, .08 * a - breath * .025, 0, 0);
		hero.root.updateMatrixWorld(true);
		const lapY = 1.02 * (1 - a) + .32 * a;
		_hilt.set(.14, lapY + .02, .22);
		hero.root.localToWorld(_hilt);
		_pole.set(.4, lapY + .15, 0);
		hero.root.localToWorld(_pole);
		solveArm(hero.armL, _hilt, _pole, false);
		hero.armL.hand.quaternion.identity();
		_hilt.set(-.1, lapY, .16);
		hero.root.localToWorld(_hilt);
		_pole.set(-.4, lapY + .12, 0);
		hero.root.localToWorld(_pole);
		solveArm(hero.armR, _hilt, _pole, false);
		hero.armR.hand.quaternion.identity();
	}
	function poseCrouch(amount) {
		const bend = Math.max(0, amount) * 1.15;
		hero.hips.position.y = .78 - .42 * (1 - Math.cos(bend));
		setBoneEuler(hero.hips, amount * .2, 0, 0);
		setBoneEuler(hero.legR.upper, -bend, 0, 0);
		setBoneEuler(hero.legL.upper, -bend, 0, 0);
		setBoneEuler(hero.legR.lower, bend * 1.15, 0, 0);
		setBoneEuler(hero.legL.lower, bend * 1.15, 0, 0);
	}
	function smoothStep(u) {
		const x = Math.max(0, Math.min(1, u));
		return x * x * (3 - 2 * x);
	}
	function inVorpalArc(p) {
		return p >= .1 && p <= .2 || p >= .42 && p <= .52 || p >= .7 && p <= .76 || p >= .87 && p <= .94;
	}
	function inSwiftArc(p) {
		return p >= .1 && p <= .2 || p >= .43 && p <= .53 || p >= .77 && p <= .87;
	}
