	let beam = null;
	function spawnSpiritBeam(p) {
		if (p > .72) {
			clearBeam();
			return;
		}
		if (!beam) {
			beam = new Group();
			for (let i = 0; i < 7; i++) {
				const mat = new MeshBasicMaterial({
					color: i % 2 ? 14217471 : 16777215,
					transparent: true,
					opacity: .9,
					depthWrite: false,
					toneMapped: false
				});
				beam.add(new Mesh(new BoxGeometry(.07, .07, .28), mat));
			}
			scene.add(beam);
		}
		const origin = new Vector3(px, 1.05, pz);
		const dest2 = new Vector3(harePos.x, 1, harePos.z);
		const travel = Math.min(1, (p - .2) / .32);
		beam.children.forEach((seg, i) => {
			const t = (i + .5) / beam.children.length;
			seg.position.lerpVectors(origin, dest2, t * travel);
			seg.lookAt(dest2);
			seg.visible = t <= travel + .05;
			seg.material.opacity = .9 * travel;
		});
	}
	function clearBeam() {
		if (!beam) return;
		scene.remove(beam);
		beam.traverse((obj) => {
			if (obj.material) obj.material.dispose();
		});
		beam = null;
	}
