	let enspellSheathKey = "";
	const enspellSheath = [];
	function clearEnspellSheath() {
		for (const mesh of enspellSheath) {
			mesh.parent?.remove(mesh);
			mesh.geometry?.dispose();
			mesh.material?.dispose();
		}
		enspellSheath.length = 0;
		enspellSheathKey = "";
	}
	function tickEnspellSheath(t) {
		const buff = useGame.getState().buffs.find((row) => row.enspell);
		const gear = hero.armR.gear;
		const element = buff && gear.visible ? buff.enspell.element : "";
		const attached = enspellSheath.length > 0 && enspellSheath[0].parent === gear;
		if (element !== enspellSheathKey || element && !attached) {
			clearEnspellSheath();
			enspellSheathKey = element;
			if (element) {
				const look2 = ELEMENT_LOOK[element];
				for (let i = 0; i < 5; i++) {
					const mote = makeElementMote(look2, i);
					mote.scale.setScalar(.72);
					mote.userData.enspell = true;
					gear.add(mote);
					enspellSheath.push(mote);
				}
			}
		}
		const n = enspellSheath.length;
		for (let i = 0; i < n; i++) {
			const spin = t * 3.2 + i * 1.3;
			enspellSheath[i].position.set(Math.cos(spin) * .06, .05 - i * .16, Math.sin(spin) * .06);
		}
	}
