	function onScytheMark(name, i) {
		if (name === "Slice") spawnImpact(1);
		else if (name === "Dark Harvest") {
			spawnElementRelease("dark", false);
			heatTint = 3807304;
			heatFlash = .22;
		} else if (name === "Shadow of Death") {
			spawnElementRelease("dark", true);
			heatTint = 1706530;
			heatFlash = .35;
		} else if (name === "Nightmare Scythe") {
			spawnImpact(0);
			heatTint = 4855904;
			heatFlash = .4;
			spawnBlindVeil();
		} else if (name === "Spinning Scythe") {
			spawnGroundRing();
			spawnImpact(0);
			spawnDust();
		} else if (name === "Vorpal Scythe") spawnCrit();
		else if (name === "Guillotine") {
			spawnImpact(i % 2 ? 1 : -1);
			if (i === 3) spawnSilenceGag();
		} else if (name === "Cross Reaper") spawnImpact(i === 0 ? -1 : 1);
		else if (name === "Spiral Hell") {
			spawnDarkHelix();
			spawnImpact(0);
			spawnDust();
		} else if (name === "Infernal Scythe") {
			spawnElementRelease("dark", true);
			spawnStatus(9249840, 1.15, 0);
			heatTint = 3807304;
			heatFlash = .35;
		} else if (name === "Entropy") {
			spawnImpact(i % 2 ? 1 : -1);
			spawnSiphonBack(10406911, 2);
			if (i === 3) spawnElementRelease("dark", false);
		} else if (name === "Catastrophe") {
			spawnElementRelease("dark", true);
			spawnDarkColumn();
			heatTint = 1312784;
			heatFlash = .45;
		} else if (name === "Quietus") {
			spawnImpact(0);
			spawnRipple(3807304);
			spawnElementRelease("dark", false);
		} else if (name === "Insurgency") {
			spawnImpact(i % 2 ? -1 : 1);
			if (i === 3) spawnElementRelease("dark", false);
		} else if (name === "Origin") {
			spawnImpact(0);
			spawnSiphonBack(8257434, 4);
			spawnSiphonBack(10406911, 4);
		}
	}
