	function poleTrail(name, p) {
		if (name === "Thunder Thrust" && p >= .3 && p <= .6) return {
			color: 13218047,
			life: .16,
			gap: .03
		};
		if (name === "Raiden Thrust" && p >= .22 && p <= .7) return {
			color: 15785983,
			life: .18,
			gap: .026
		};
		if (name === "Geirskogul" && p >= .35 && p <= .85) return {
			color: 16775362,
			life: .16,
			gap: .03
		};
		if (name === "Sonic Thrust" && p >= .2 && p <= .7) return {
			color: 14149618,
			life: .14,
			gap: .028
		};
		if (name === "Camlann's Torment" && p >= .4 && p <= .75) return {
			color: 16775362,
			life: .16,
			gap: .03
		};
		if ((name === "Vorpal Thrust" || name === "Drakesbane" || name === "Skewer") && p >= .15 && p <= .9) return {
			color: 16773296,
			life: .1,
			gap: .03
		};
		return null;
	}
	function onPoleMark(name, i) {
		if (name === "Double Thrust" || name === "Diarmuid") spawnImpact(i === 0 ? -1 : 1);
		else if (name === "Thunder Thrust") {
			spawnElementRelease("thunder", false);
			spawnShock();
		} else if (name === "Raiden Thrust") {
			spawnElementRelease("thunder", true);
			spawnShock();
			spawnGroundRing();
		} else if (name === "Leg Sweep") {
			spawnDust();
			spawnGroundRing();
			spawnStun();
		} else if (name === "Penta Thrust") spawnImpact((i % 2 ? 1 : -1) * .6, 1.05 + i % 3 * .06);
		else if (name === "Vorpal Thrust") spawnCrit();
		else if (name === "Skewer") {
			spawnImpact(0, 1.1);
			if (i === 2) spawnCrit();
		} else if (name === "Wheeling Thrust") {
			spawnGroundRing();
			spawnImpact(0);
			spawnDust();
		} else if (name === "Impulse Drive") {
			spawnImpact(i === 0 ? -1 : 0, i === 0 ? 1.1 : 1.25);
			if (i === 1) {
				spawnShock();
				spawnDust();
			}
		} else if (name === "Sonic Thrust") {
			spawnSonicCone();
			spawnWindSlash(14149618);
		} else if (name === "Stardiver") {
			spawnImpact((i - 1.5) * .7, 1.4 - i * .12);
			if (i === 3) spawnDust();
		} else if (name === "Geirskogul") {
			spawnHolyBurst();
			spawnShock();
		} else if (name === "Camlann's Torment") {
			spawnHolyBurst();
			spawnShock();
			spawnDust();
			spawnGroundRing();
		} else if (name === "Drakesbane") spawnCrit();
		else spawnImpact(0);
	}
	function onAxeMark(name, i) {
		if (name === "Shield Break") {
			spawnMetal(13684944);
			spawnStatus(13224393, 1.45, 0);
		} else if (name === "Iron Tempest") {
			spawnImpact(0);
			spawnDust();
		} else if (name === "Sturmwind") {
			spawnImpact(i === 0 ? -1 : 1);
			spawnDust();
		} else if (name === "Armor Break") {
			spawnMetal(9276816);
			spawnStatus(8353704, 1.2, 0);
		} else if (name === "Keen Edge" || name === "Raging Rush") spawnCrit();
		else if (name === "Weapon Break") {
			spawnImpact(1);
			spawnStatus(12875066, 1.3, 0);
		} else if (name === "Full Break") {
			spawnImpact(0);
			spawnRipple(6955640);
			spawnStatus(16777215, 1.62, -.6);
			spawnStatus(13632027, 1.42, -.2);
			spawnStatus(6724095, 1.22, .2);
			spawnStatus(16766720, 1.02, .6);
		} else if (name === "Steel Cyclone") {
			spawnImpact(0);
			spawnVortex();
		} else if (name === "Fell Cleave") {
			if (i === 0) {
				spawnGroundRing();
				spawnDust();
			}
			const a = i / 3 * Math.PI * 2;
			spawnFlashAt(harePos.x + Math.cos(a) * .5, 1.05, harePos.z + Math.sin(a) * .5);
		} else if (name === "Upheaval") {
			spawnDebris(i === 3 ? 1.7 : .65 + i * .2);
			spawnImpact(i % 2 ? 1 : -1);
		}
	}
