	function liveSwingSeconds(sheet, buffs) {
		const slow = weaknessDelayFactor(useGame.getState().weakness);
		if (sheet.skillName === "Archery" || sheet.skillName === "Marksmanship" || sheet.skillName === "Throwing") return sheet.swing.seconds * slow;
		const hasso = buffs.some((buff) => buff.name === "Hasso") && twoHandKind(sheet.skillName);
		const blows = buffs.some((buff) => buff.name === "Last Resort") && twoHandKind(sheet.skillName) ? sheet.desperateBlows || 0 : 0;
		const samba = playerFoe() === "kin" ? useGame.getState().kinEnfeebles.some((row) => row.name === "Haste Daze") : playerFoe() === "hare" ? useGame.getState().hareEnfeebles.some((row) => row.name === "Haste Daze") : false;
		let seconds = swingTiming(sheet.swing.baseDelay, {
			equipment: 0,
			magic: hasteMagic(buffs),
			jobAbility: (hasso ? 102 : 0) + blows + (samba ? 51 : 0),
			dualWield: sheet.dualWield || 0
		}).seconds;
		if (buffs.some((buff) => buff.name === "Hundred Fists")) seconds *= HUNDRED_FISTS_DELAY;
		if (buffs.some((buff) => buff.name === "Velocity Shot")) seconds *= VELOCITY_SLOW;
		return seconds * slow;
	}
