	const UTSU_RADIUS = .86;
	const UTSU_FLY = .26;
	const UTSU_SPIN = 1.7;
	const utsuBars = [];
	function disposeUtsuBar(bar) {
		scene.remove(bar.mesh);
		bar.mesh.material?.dispose();
		if (bar.mesh.userData.ownGeo) bar.mesh.geometry?.dispose();
	}
	function clearUtsuBars() {
		for (const bar of utsuBars) disposeUtsuBar(bar);
		utsuBars.length = 0;
	}
	function makeUtsuBar(i, n) {
		const peak = i % 2 ? .78 : .62;
		const mesh = new Mesh(new BoxGeometry(.2, 1.18, .07), chantMat(i % 2 ? 15204312 : 10342294, peak));
		mesh.userData.ownGeo = true;
		scene.add(mesh);
		return {
			mesh,
			ang: i / n * Math.PI * 2 + .35,
			phase: "fly",
			rad: .14,
			t: 0,
			slot: i,
			peak
		};
	}
	function killUtsuBar(bar) {
		if (bar.phase === "die") return;
		bar.phase = "die";
		bar.t = 0;
	}
	function placeUtsuBar(bar, rad, t) {
		const bob = Math.sin(t * 2.2 + bar.slot) * .035;
		bar.mesh.position.set(px + Math.cos(bar.ang) * rad, .72 + bob, pz + Math.sin(bar.ang) * rad);
		bar.mesh.rotation.y = Math.PI / 2 - bar.ang;
	}
	function launchPlayerShadows(count) {
		clearUtsuBars();
		const n = Math.max(1, Math.min(4, count));
		for (let i = 0; i < n; i++) utsuBars.push(makeUtsuBar(i, n));
		const flash2 = new Mesh(new SphereGeometry(.28, 10, 8), chantMat(15269844, .4));
		flash2.position.set(px, .95, pz);
		ninPut(flash2, .2, 0, 0, 0, .65, .08);
	}
	const BLINK_RADIUS = 1.14;
	const BLINK_FLY = .34;
	const BLINK_SPIN = -2.4;
	const blinkOrbs = [];
	let blinkSpin = 0;
	function disposeBlinkOrb(orb) {
		scene.remove(orb.mesh);
		orb.mesh.traverse((obj) => {
			obj.geometry?.dispose();
			obj.material?.dispose();
		});
	}
	function makeBlinkOrb(i) {
		const g = new Group();
		const shell = new Mesh(new SphereGeometry(.16, 12, 10), chantMat(i % 2 ? 12120264 : 14221288, .7));
		shell.userData.ownGeo = true;
		const core = new Mesh(new SphereGeometry(.07, 8, 6), chantMat(16056304, .95));
		core.userData.ownGeo = true;
		g.add(shell);
		g.add(core);
		scene.add(g);
		return {
			mesh: g,
			shell,
			core,
			offset: 0,
			goal: 0,
			phase: "fly",
			rad: .12,
			t: 0,
			shellPeak: .7,
			corePeak: .95
		};
	}
	function killBlinkOrb(orb) {
		if (orb.phase === "die") return;
		orb.phase = "die";
		orb.t = 0;
	}
	function placeBlinkOrb(orb, rad, t) {
		const ang = blinkSpin + orb.offset;
		const bob = Math.sin(t * 2.6 + orb.offset * 2) * .07;
		orb.mesh.position.set(px + Math.cos(ang) * rad, 1.18 + bob, pz + Math.sin(ang) * rad);
	}
	function steerBlinkOrb(orb, dt) {
		const d = Math.atan2(Math.sin(orb.goal - orb.offset), Math.cos(orb.goal - orb.offset));
		orb.offset += d * Math.min(1, dt * 5);
	}
	/**
	* Blink shadows. Utsusemi is the tall copies. These are wind spheres,
	* one for each charge still up, whether the buff came from Blink,
	* Zephyr Mantle, or Aerial Armor.
	*/
	function tickBlinkShadows(dt, t) {
		blinkSpin += BLINK_SPIN * dt;
		const buff = useGame.getState().buffs.find((row) => row.name === "Blink");
		const charges = buff && (buff.charges ?? 0) > 0 ? Math.min(8, Math.floor(buff.charges)) : 0;
		const alive = () => blinkOrbs.filter((orb) => orb.phase !== "die");
		if (charges <= 0) for (const orb of blinkOrbs) killBlinkOrb(orb);
		else {
			let extra = alive().length - charges;
			while (extra > 0) {
				let killed = false;
				for (let i = blinkOrbs.length - 1; i >= 0; i--) {
					if (blinkOrbs[i].phase === "die") continue;
					killBlinkOrb(blinkOrbs[i]);
					killed = true;
					break;
				}
				if (!killed) break;
				extra--;
			}
			const have = alive().length;
			for (let i = have; i < charges; i++) blinkOrbs.push(makeBlinkOrb(i));
		}
		const living = alive();
		const n = living.length;
		for (let i = 0; i < n; i++) living[i].goal = n > 0 ? i / n * Math.PI * 2 : 0;
		for (let i = blinkOrbs.length - 1; i >= 0; i--) {
			const orb = blinkOrbs[i];
			if (orb.phase === "fly") {
				if (orb.t === 0) orb.offset = orb.goal;
				orb.t += dt;
				const u = Math.min(1, orb.t / BLINK_FLY);
				orb.rad = .12 + 1.02 * (1 - (1 - u) ** 3);
				steerBlinkOrb(orb, dt);
				placeBlinkOrb(orb, orb.rad, t);
				const pulse = .9 + Math.sin(t * 5 + orb.offset) * .1;
				orb.mesh.scale.setScalar(pulse);
				if (u >= 1) orb.phase = "orbit";
			} else if (orb.phase === "orbit") {
				steerBlinkOrb(orb, dt);
				placeBlinkOrb(orb, BLINK_RADIUS, t);
				orb.mesh.scale.setScalar(.92 + Math.sin(t * 4.2 + orb.offset) * .08);
			} else {
				orb.t += dt;
				const u = Math.min(1, orb.t / .28);
				orb.rad += dt * 1.8;
				orb.shell.material.opacity = orb.shellPeak * (1 - u);
				orb.core.material.opacity = orb.corePeak * (1 - u);
				placeBlinkOrb(orb, orb.rad, t);
				orb.mesh.scale.setScalar(1 + u * .65);
				if (u >= 1) {
					disposeBlinkOrb(orb);
					blinkOrbs.splice(i, 1);
				}
			}
		}
	}
	const MANEUVER_RADIUS = .98;
	const MANEUVER_FLY = .32;
	const MANEUVER_SPIN = 1.25;
	const maneuverOrbs = [];
	let maneuverSpin = 0;
	let autoCastFx = false;
	function maneuverOrbColors(element) {
		if (element === "thunder") return {
			shell: 15917386,
			core: 16774856
		};
		const look2 = ELEMENT_LOOK[element] || ELEMENT_LOOK.light;
		if (element === "earth") return {
			shell: 15123306,
			core: 16773572
		};
		if (element === "dark") return {
			shell: 8015523,
			core: 13807871
		};
		return {
			shell: look2.color,
			core: look2.accent
		};
	}
	function disposeManeuverOrb(orb) {
		scene.remove(orb.mesh);
		orb.mesh.traverse((obj) => {
			obj.geometry?.dispose();
			obj.material?.dispose();
		});
	}
	function makeManeuverOrb(element) {
		const hue = maneuverOrbColors(element);
		const g = new Group();
		const shell = new Mesh(new SphereGeometry(.13, 12, 10), chantMat(hue.shell, .82));
		shell.userData.ownGeo = true;
		const core = new Mesh(new SphereGeometry(.055, 8, 6), chantMat(hue.core, .96));
		core.userData.ownGeo = true;
		g.add(shell);
		g.add(core);
		scene.add(g);
		return {
			mesh: g,
			shell,
			core,
			element,
			offset: 0,
			goal: 0,
			phase: "fly",
			rad: .12,
			t: 0,
			shellPeak: .82,
			corePeak: .96
		};
	}
	function killManeuverOrb(orb) {
		if (orb.phase === "die") return;
		orb.phase = "die";
		orb.t = 0;
	}
	function placeManeuverOrb(orb, rad, t) {
		const ang = maneuverSpin + orb.offset;
		const bob = Math.sin(t * 2.4 + orb.offset * 2) * .06;
		orb.mesh.position.set(px + Math.cos(ang) * rad, 1.02 + bob, pz + Math.sin(ang) * rad);
		orb.mesh.rotation.y = t * .8 + orb.offset;
	}
	function steerManeuverOrb(orb, dt) {
		const d = Math.atan2(Math.sin(orb.goal - orb.offset), Math.cos(orb.goal - orb.offset));
		orb.offset += d * Math.min(1, dt * 5);
	}
	/**
	* One orb per maneuver still up, in that element's color.
	* They circle the master the way Utsusemi's images do.
	*/
	function tickManeuverOrbs(dt, t) {
		maneuverSpin += MANEUVER_SPIN * dt;
		const pet = peekAutomaton();
		const wanted = pet ? pet.maneuvers.map((row) => row.element) : [];
		const alive = () => maneuverOrbs.filter((orb) => orb.phase !== "die");
		const living = alive();
		const claimed = /* @__PURE__ */ new Set();
		for (const element of wanted) {
			const orb = living.find((row) => !claimed.has(row) && row.element === element);
			if (orb) claimed.add(orb);
			else claimed.add(maneuverOrbs[maneuverOrbs.push(makeManeuverOrb(element)) - 1]);
		}
		for (const orb of living) if (!claimed.has(orb)) killManeuverOrb(orb);
		const still = alive();
		const n = still.length;
		for (let i = 0; i < n; i++) still[i].goal = n > 0 ? i / n * Math.PI * 2 : 0;
		for (let i = maneuverOrbs.length - 1; i >= 0; i--) {
			const orb = maneuverOrbs[i];
			if (orb.phase === "fly") {
				if (orb.t === 0) orb.offset = orb.goal;
				orb.t += dt;
				const u = Math.min(1, orb.t / MANEUVER_FLY);
				const ease = 1 - (1 - u) ** 3;
				orb.rad = .12 + .86 * ease;
				steerManeuverOrb(orb, dt);
				placeManeuverOrb(orb, orb.rad, t);
				orb.mesh.scale.setScalar(.75 + ease * .25);
				if (u >= 1) orb.phase = "orbit";
			} else if (orb.phase === "orbit") {
				steerManeuverOrb(orb, dt);
				placeManeuverOrb(orb, MANEUVER_RADIUS, t);
				orb.mesh.scale.setScalar(.94 + Math.sin(t * 4 + orb.offset) * .06);
			} else {
				orb.t += dt;
				const u = Math.min(1, orb.t / .28);
				orb.rad += dt * 1.6;
				orb.shell.material.opacity = orb.shellPeak * (1 - u);
				orb.core.material.opacity = orb.corePeak * (1 - u);
				placeManeuverOrb(orb, orb.rad, t);
				orb.mesh.scale.setScalar(1 + u * .45);
				if (u >= 1) {
					disposeManeuverOrb(orb);
					maneuverOrbs.splice(i, 1);
				}
			}
		}
	}
