	function spawnNinRelease(nin, x, z, who) {
		const kind = nin?.kind;
		const tier = ninTier(nin);
		const element = nin?.element;
		if (kind === "nuke") {
			if (element === "fire") spawnKatonLand(tier, x, z);
			else if (element === "ice") spawnHyotonLand(tier, x, z);
			else if (element === "wind") spawnHutonLand(tier, x, z);
			else if (element === "earth") spawnDotonLand(tier, x, z);
			else if (element === "thunder") spawnRaitonLand(tier, x, z);
			else if (element === "water") spawnSuitonLand(tier, x, z);
			return;
		}
		if (kind === "huton") {
			spawnHutonLand(tier, x, z);
			return;
		}
		if (kind === "shadow") {
			if (nin?.shadows > 0) spawnUtsusemiLand(nin.shadows, x, z, who);
			return;
		}
		if (kind === "invisible") {
			spawnTonkoLand(tier, x, z);
			return;
		}
		if (kind === "sneak") {
			spawnMonomiLand(x, z);
			return;
		}
		if (kind === "blind") spawnKurayamiLand(tier, x, z);
		else if (kind === "slow") spawnHojoLand(tier, x, z);
		else if (kind === "poison") spawnDokumoriLand(x, z);
		else if (kind === "paralyze") spawnJubakuLand(x, z);
	}
