		pan.rotation.z = .4;
		pan.userData.ownGeo = true;
		scene.add(pan);
		embers.push({
			mesh: pan,
			life: .32,
			max: .32,
			vy: -.6,
			vx: face.x * 1.6,
			vz: face.z * 1.6,
			hold: .04
		});
