		const p = muzzleAt();
		const fat = name === "Coronach" || name === "Wildfire" || name === "Detonator" || name === "Slug Shot";
		const flash = new Mesh(new SphereGeometry(fat ? .16 : .08, 8, 6), shotFxMat(color, .95));
		flash.position.set(p.x, p.y, p.z);
