		const right = new Vector3(nose.z, 0, -nose.x);
		g.position.set(fightX + right.x * side * .2 + nose.x * .55, y, fightZ + right.z * side * .2 + nose.z * .55);
		g.lookAt(fightX + nose.x * 2, y, fightZ + nose.z * 2);
		scene.add(g);
