		const dur = .75 + lv * .1;
		const hex = {
			Liquefaction: 16737050,
			Impaction: 16772842,
			Detonation: 11927112,
			Scission: 12888666,
			Reverberation: 8304895,
			Induration: 14152191,
			Compression: 12616284,
			Transfixion: 16775376,
			Fusion: 16766714,
			Fragmentation: 14077706,
			Distortion: 10469087,
			Gravitation: 7020858,
			Light: 16777215,
			Darkness: 7020858,
			Radiance: 16775376,
			Umbra: 4276548
		}[name] || 16777215;
