function makeBow(toonMat) {
	const g = new Group();
	const gold = 13942870;
	const grip = part(new BoxGeometry(.14, .3, .14), 2762276, toonMat, true);
	g.add(grip);
	const wrap = part(new BoxGeometry(.18, .05, .16), gold, toonMat, false);
	wrap.position.y = .08;
	const wrap2 = wrap.clone();
	wrap2.position.y = -.12;
	g.add(wrap, wrap2);
	const bulge = (t) => -Math.sin(t * Math.PI) * .55 * (1 - t * .2);
	const span = (az, ay, bz, by, color) => {
		const dz = bz - az;
		const dy = by - ay;
		const len = Math.hypot(dz, dy) + .06;
		const mesh = part(new BoxGeometry(.16, len, .16), color, toonMat, true);
		mesh.position.set(0, (ay + by) / 2, (az + bz) / 2);
		mesh.rotation.x = Math.atan2(dz, dy);
		g.add(mesh);
	};
	for (const sign of [1, -1]) {
		const samples = 7;
		let pz = 0;
		let py = sign * .16;
		for (let i = 1; i <= samples; i++) {
			const t = i / samples;
			const y = sign * (.16 + t * .96);
			const z = bulge(t);
			span(pz, py, z, y, t < .45 ? 1710618 : 986895);
			pz = z;
			py = y;
		}
	}
	const tipU = part(new BoxGeometry(.13, .16, .13), gold, toonMat, false);
	tipU.position.set(0, 1.16, 0);
	const tipD = tipU.clone();
	tipD.position.set(0, -1.16, 0);
	g.add(tipU, tipD);
	const string = part(new BoxGeometry(.03, 2.24, .03), 12887906, toonMat, false);
	string.position.set(0, 0, .02);
	string.name = "string";
	g.add(string);
	g.userData.tipUp = new Vector3(0, 1.16, 0);
	g.userData.tipDown = new Vector3(0, -1.16, 0);
	return g;
}
