function buildGear(id, toonMat) {
	if (id === "kunai-off") id = "kunai";
	if (id === "bronze-dagger-off") id = "bronze-dagger";
	const g = new Group();
	const add = (w, h, d, color, x, y, z, outline = false) => {
		g.add(gearPart(toonMat, w, h, d, color, x, y, z, outline));
	};
	const wood = 9263666;
	if (id === "cesti") {
		add(.13, .05, .11, GUARD, 0, .03, .08);
		return g;
	}
	if (id === "cat-baghnakhs") {
		add(.15, .045, .12, PUPPET_GOLD, 0, .03, .07);
		add(.028, .035, .09, PUPPET_FEATHER, .045, .02, .13);
		add(.028, .035, .1, PUPPET_FEATHER, 0, .015, .14);
		add(.028, .035, .09, PUPPET_FEATHER, -.045, .02, .13);
		return g;
	}
	if (id === "bronze-dagger") {
		add(.07, .05, .07, GUARD, 0, .08, 0);
		add(.045, .12, .045, HAIR, 0, 0, 0);
		add(.16, .035, .08, GUARD, 0, -.07, 0);
		add(.05, .32, .08, BLADE, 0, -.26, 0, true);
		return g;
	}
	if (id === "kunai") {
		add(.09, .02, .09, GUARD, 0, .12, 0);
		add(.045, .12, .045, HAIR, 0, .04, 0);
		add(.1, .4, .05, BLADE, 0, -.22, 0, true);
		return g;
	}
	if (id === "trainee-burin") {
		add(.05, .14, .05, wood, 0, .05, 0);
		add(.1, .03, .06, 9075285, 0, -.04, 0);
		add(.045, .62, .03, BLADE, 0, -.36, 0, true);
		return g;
	}
	if (id === "rusty-greatsword") {
		add(.14, .08, .14, 9069128, 0, .22, 0);
		add(.07, .32, .07, HAIR, 0, .02, 0);
		add(.4, .07, .16, 9069128, 0, -.16, 0);
		add(.12, 1.02, .16, 10119749, 0, -.7, 0, true);
		return g;
	}
	if (id === "mumeito") {
		add(.06, .3, .06, HAIR, 0, .06, 0);
		add(.16, .04, .16, GUARD, 0, -.12, 0);
		add(.055, .92, .1, BLADE, 0, -.62, 0, true);
		return g;
	}
	if (id === "hardwood-katana") {
		add(.07, .26, .07, wood, 0, .08, 0);
		add(.16, .05, .09, wood, 0, -.08, 0);
		add(.055, .92, .09, 9263666, 0, -.56, 0, true);
		return g;
	}
	if (id === "bronze-axe") {
		add(.055, .44, .055, wood, 0, -.06, 0);
		add(.3, .16, .07, BRONZE, .17, -.3, 0, true);
		return g;
	}
	if (id === "butterfly-axe") {
		add(.07, 1.02, .07, wood, 0, -.2, 0);
		add(.4, .3, .1, BRONZE, .1, -.72, 0, true);
		return g;
	}
	if (id === "bronze-zaghnal") {
		add(.055, 1.12, .055, wood, 0, -.2, 0);
		add(.34, .08, .06, BLADE, -.16, -.74, 0, true);
		return g;
	}
	if (id === "harpoon") {
		add(.048, .36, .048, wood, 0, .24, 0);
		add(.05, 1.15, .05, wood, 0, -.32, 0);
		add(.1, .26, .08, BLADE, 0, -1.02, 0, true);
		return g;
	}
	if (id === "ash-club") {
		add(.08, .34, .08, wood, 0, .04, 0);
		add(.22, .3, .22, 7028258, 0, -.3, 0, true);
		return g;
	}
	if (id === "ash-staff") {
		add(.1, 1.2, .1, wood, -.03, .02, 0, true);
		add(.15, .08, .15, GUARD, -.03, .64, 0);
		add(.14, .08, .14, GUARD, -.03, -.6, 0);
		return g;
	}
	const onion = id === "onion-sword";
	add(.12, .07, .12, GUARD, 0, .13, 0);
	add(.07, .2, .07, onion ? wood : HAIR, 0, 0, 0);
	add(.34, .06, .16, GUARD, 0, -.13, 0);
	const blade = gearPart(toonMat, .1, onion ? .6 : .7, .16, onion ? 12043440 : BLADE, 0, onion ? -.45 : -.5, 0, true);
	blade.rotation.y = Math.PI / 4;
	g.add(blade);
	return g;
}
function paintGear(hero, loadout, job) {
	const kind = ITEMS[loadout.sub ?? ""]?.kind ?? "";
	hero.armL.shield.visible = kind === "Shield";
	hero.armR.shield.visible = false;
	if (kind === "Shield") hero.armL.shield.material.color.setHex(loadout.sub === "marine-shield" ? 3108517 : 10117683);
	if (hero.armL.offBlade) hero.armL.offBlade.visible = isOffhandWeapon(ITEMS[loadout.sub ?? ""]);
	hero.bow.visible = false;
	hero.crossbow.visible = false;
	hero.flint.visible = false;
	hero.pebble.visible = false;
	applyJobModel(hero, job);
}
