	body.position.set(0, y0, 0);
	body.rotation.set(0, 0, 0);
	L.position.set(.48, .02, .18);
	R.position.set(-.48, .02, .18);
	L.rotation.set(0, .35, .15);
	R.rotation.set(0, -.35, -.15);
	L.scale.setScalar(1);
	R.scale.setScalar(1);
	hideCrabFx(rig);
	paintCrabShell(rig, 0);
	if (motion === "auto") poseCrabAuto(rig, u, side, y0);
	else if (motion === "Big Scissors") poseCrabScissors(rig, u, y0);
	else if (motion === "Bubble Shower") poseCrabShower(rig, u, y0);
	else if (motion === "Bubble Curtain") poseCrabCurtain(rig, u);
	else if (motion === "Scissor Guard") poseCrabGuard(rig, u);
	else if (motion === "Metallic Body") poseCrabMetal(rig, u, y0);
