	const brace = left ? rig.clawR : rig.clawL;
	rig.body.rotation.x = -.7 * wind * (1 - hit) + 1.05 * hit;
	rig.body.rotation.z = (left ? -1 : 1) * .22 * hit;
	rig.body.position.z = -.16 * wind * (1 - hit) + 1.05 * hit;
	rig.body.position.y = y0 + wind * .06 + hit * .1;
	strike.rotation.y = sign * .35 - sign * (hit * 2.35 - wind * .15);
	strike.rotation.z = sign * (.15 + wind * 1.15 - hit * 1.55);
	strike.rotation.x = -wind * .95;
	strike.position.z = .18 + hit * .95;
	strike.position.x = sign * (.48 - hit * .22);
	strike.scale.setScalar(1 + hit * 1.05);
	brace.rotation.y = -sign * .35 - sign * wind * .25;
	brace.rotation.z = -sign * (.15 + wind * .3);
	rig.streak.visible = hit > .5;
	rig.streak.position.set(sign * .15, .16, 1.15);
	rig.streak.rotation.set(.15, -sign * .55, sign * .35);
	rig.streak.material.opacity = Math.min(1, (hit - .5) / .2);
	rig.streak.scale.set(1.35, 1.6, 1);
	rig.chop.visible = hit > .62;
	rig.chop.position.set(sign * .1, .08, 1.35);
	rig.chop.scale.setScalar(.9 + hit * 3.4);
	rig.chop.material.opacity = Math.max(0, (1 - (hit - .62) / .38) * .9);
