	rig.clawR.position.set(-.48 + cross * .36, .08 + cross * .26, .18 + cross * .42);
	rig.clawL.rotation.set(-.25 * cross, .35 - cross * 2.05, .15 + cross * 1.05);
	rig.clawR.rotation.set(.4 * cross, -.35 + cross * 2.05, -.15 - cross * .2);
