function pulseCrystal(root, elapsed, selected) {
	const bits = root.userData.bits;
	const pulse = .5 + .5 * Math.sin(elapsed * 1.7);
	bits.spire.material.opacity = .48 + pulse * .4;
	bits.core.material.opacity = .7 + pulse * .3;
	bits.ring.material.opacity = .22 + pulse * .4;
	root.position.y = Math.sin(elapsed * 1.25) * .045;
	root.rotation.y = elapsed * .16;
	for (let i = 0; i < bits.shards.length; i++) {
		bits.shards[i].material.opacity = .4 + pulse * .35;
		const base = .32 + i % 2 * .16;
		bits.shards[i].position.y = base + Math.sin(elapsed * 1.5 + i) * .035;
	}
	bits.select.visible = selected;
}
function buildHomeCrystal() {
	const root = new Group();
	const glow = new MeshBasicMaterial({
		color: 4034047,
		transparent: true,
		opacity: .75,
		depthWrite: false,
		toneMapped: false
	});
	const coreMat = new MeshBasicMaterial({
		color: 14152703,
		transparent: true,
		opacity: .9,
		depthWrite: false,
		toneMapped: false
	});
	const spire = new Mesh(new OctahedronGeometry(.42, 0), glow);
	spire.scale.set(.62, 1.85, .62);
	spire.position.y = 1.05;
	const core = new Mesh(new OctahedronGeometry(.2, 0), coreMat);
	core.scale.set(.5, 1.7, .5);
	core.position.y = 1.05;
	const shards = [];
	for (let i = 0; i < 5; i++) {
		const shard = new Mesh(new OctahedronGeometry(.16, 0), glow.clone());
		const a = i / 5 * Math.PI * 2;
		shard.position.set(Math.cos(a) * .34, .32 + i % 2 * .16, Math.sin(a) * .34);
		shard.scale.set(.5, .95 + i % 3 * .28, .5);
		shard.rotation.y = a;
		shard.rotation.z = i % 2 ? .35 : -.28;
		shards.push(shard);
		root.add(shard);
	}
	const ring = new Mesh(new RingGeometry(.42, .68, 6), glow.clone());
	ring.rotation.x = -Math.PI / 2;
	ring.position.y = .03;
	const select = new Mesh(new RingGeometry(.72, .86, 32), new MeshBasicMaterial({
		color: 9357567,
		transparent: true,
		opacity: .85,
		depthWrite: false,
		toneMapped: false,
		side: 2
	}));
	select.rotation.x = -Math.PI / 2;
	select.position.y = .045;
	select.visible = false;
	root.add(spire, core, ring, select);
	root.userData.bits = {
		spire,
		core,
		shards,
		ring,
		select
	};
	return root;
}
