function talkFisher(who, s) {
	const chosen = s.quests?.rivalry;
	if (chosen !== "gallijaux" && chosen !== "joulet") {
		useGame.setState({ rivalryAsk: who, homeAsk: false });
		return;
	}
	if (chosen !== who) {
		s.pushLog(who === "gallijaux" ? "Gallijaux: What's this? You're helping me brother, are you? Be gone with you, then! Out of my sight!" : "Joulet: Ah, so you've been helping my brother, have you!? Traitor! Turncoat! Be gone with you!", "info");
		return;
	}
	const inv = { ...s.inventory ?? {} };
	const held = Math.max(0, Math.floor(inv["moat-carp"] ?? 0));
	let given = Math.max(0, Math.floor(Number(s.quests?.carpGiven) || 0));
	const quests = { ...s.quests ?? {}, rivalry: who, carpGiven: given, carpHand: 0 };
	if (held > 0) {
		inv["moat-carp"] = 0;
		given += held;
		quests.carpGiven = given;
		quests.carpHand = held;
		useGame.setState({
			inventory: inv,
			gil: Math.min(999999999, (s.gil ?? 0) + held * 10),
			quests
		});
	} else if ((Number(s.quests?.carpHand) || 0) !== 0) useGame.setState({ quests });
	const word = given === 1 ? "carp" : "carps";
	s.pushLog(who === "gallijaux" ? `Gallijaux: How's it going with you? I've got ${given} ${word} now--don't let me down!` : `Joulet: How goes it? I've got a hold of ${given} ${word} now. Keep bringing them--I wouldn't want to lose to my brother!`, "info");
}
function fisherTally(state, who) {
	if (state?.quests?.rivalry !== who) return "";
	return carpTurnLine(state.quests?.carpHand);
}
